conditions.value_template:
{% set ymd = now().strftime('%Y-%m-%d') %}
{% set alternate_start = as_datetime('2030-09-13').date() %}
{{ ('2030-08-29' <= ymd <= '2030-09-11') or (now().date() >= alternate_start and ((now().date() - alternate_start).days % 2 == 0)) }}

sequence.value_template:
{% set start = today_at() %}
{% set end = start + timedelta(days=2) %}
{% set response = rain_forecast if rain_forecast is defined and rain_forecast is mapping else {} %}
{% set provider = response.get('weather.test_rain') %}
{% set entries = provider.get('forecast') if provider is mapping else none %}
{% set forecasts = entries if entries is sequence and entries is not string and entries is not mapping else [] %}
{% set ns = namespace(wet=false) %}
{% for item in forecasts %}
  {% set dt = as_datetime(item.get('datetime'), none) if item is mapping else none %}
  {% if dt is not none %}
    {% set period_start = as_local(dt) %}
    {% set period_end = period_start + timedelta(hours=12) %}
    {% set probability = item.get('precipitation_probability') %}
    {% if period_start < end and period_end > start and is_number(probability) %}
      {% set ns.wet = ns.wet or probability | float > 50 %}
    {% endif %}
  {% endif %}
{% endfor %}
{% set last_rain = states('sensor.test_rain_date') %}
{% set rain_today = states('sensor.test_rain_today') %}
{% set rain_rate = states('sensor.test_rain_rate') %}
{{ not ((rain_today | float(0)) > 0
        or (rain_rate | float(0)) > 0
        or last_rain in [now().date().isoformat(), (now().date() - timedelta(days=1)).isoformat()]
        or ns.wet) }}

conditions.value_template:
{% set forecasts = daily_forecast.get('weather.test_temperature', {}).get('forecast', []) if daily_forecast is defined and daily_forecast is mapping else [] %}
{% set ns = namespace(high=none) %}
{% for item in forecasts %}
  {% set dt = item.get('datetime') if item is mapping else none %}
  {% if dt is not none and as_local(as_datetime(dt)).date() == now().date() %}
    {% set ns.high = item.get('temperature') %}
  {% endif %}
{% endfor %}
{{ ns.high is not none and (ns.high | float) > 95 }}

